import { Data, Effect } from "effect"

export interface ReleaseDraft {
  readonly version: string
  readonly files: ReadonlyArray<string>
}

export interface PublicationGateway {
  readonly loadDraft: (
    releaseId: string,
  ) => Effect.Effect<ReleaseDraft, Error>
  readonly renderManifest: (
    draft: ReleaseDraft,
  ) => Effect.Effect<string, Error>
  readonly uploadManifest: (
    releaseId: string,
    manifest: string,
  ) => Effect.Effect<string, Error>
}

export class PublishReleaseError extends Data.TaggedError("PublishReleaseError")<{
  readonly releaseId: string
  readonly cause: unknown
}> {}

export const publishRelease = Effect.fn("publishRelease")(
  function* (gateway: PublicationGateway, releaseId: string) {
    const draft = yield* gateway.loadDraft(releaseId)
    const manifest = yield* gateway.renderManifest(draft)
    const location = yield* gateway.uploadManifest(releaseId, manifest)

    return {
      releaseId,
      version: draft.version,
      location,
    }
  },
  (effect, _gateway, releaseId) =>
    effect.pipe(
      Effect.mapError((cause) => new PublishReleaseError({ releaseId, cause })),
    ),
)
